  const n=src.length, act=aS/n, inh=iS/n, act2=aS2/n, inh2=iS2/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.06+sy*0.01-t*0.6)*0.5+Math.cos(sx*0.02+sy*0.05+t*0.5)*0.5)/3+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
